// This file is generated by AI.

// 项目会话: 记住每个项目上次打开的场景选项卡, 下次打开时恢复。
//
// 只存**场景文件路径**, 不存资源页/差异页/配音工作台这些临时选项卡: 它们要么是打开文件
// 的副产物 (资源页), 要么是一次性工具 (差异、说明), 恢复出来只会让人困惑。
// 存的是路径而不是内容 —— 内容永远以磁盘为准。

import { bindingKey } from './bindings';

export interface ProjectSession {
  /** 已打开的场景文件绝对路径, 按选项卡顺序 */
  tabs: string[];
  /** 上次激活的那个场景文件; null 表示当时激活的不是场景卡 */
  activeTab: string | null;
  updatedAt: number;
}

/** 单个项目最多恢复多少个选项卡 */
export const SESSION_TAB_LIMIT = 20;
/** 最多记住多少个项目 (超出的按最近更新淘汰) */
export const SESSION_PROJECT_LIMIT = 50;

const STORAGE_KEY = 'webgal-ink.sessions';

/** 选项卡的最小形状 (只取恢复需要的字段, 免得这个模块依赖选项卡模型) */
interface TabLike {
  id: string;
  kind: string;
  /** 只有场景/资源类选项卡带路径 (工作台、说明页没有) */
  path?: string;
}

/**
 * 从选项卡序列里取出要恢复的场景文件 (按显示顺序, 去重, 截断)。
 */
export function collectSceneTabs(tabs: readonly TabLike[]): string[] {
  const seen = new Set<string>();
  const paths: string[] = [];
  for (const tab of tabs) {
    if (tab.kind !== 'scene' || !tab.path) continue;
    const key = tab.path.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    paths.push(tab.path);
    if (paths.length >= SESSION_TAB_LIMIT) break;
  }
  return paths;
}

/** 由当前选项卡状态算出要保存的会话。 */
export function sessionFromTabs(tabs: readonly TabLike[], activeTabId: string | null): ProjectSession {
  const active = tabs.find((tab) => tab.id === activeTabId);
  return {
    tabs: collectSceneTabs(tabs),
    activeTab: active?.kind === 'scene' && active.path ? active.path : null,
    updatedAt: Date.now(),
  };
}

/** 清理持久化里读到的对象; 结构不对时返回 null。 */
export function normalizeSession(raw: unknown): ProjectSession | null {
  if (!raw || typeof raw !== 'object') return null;
  const record = raw as Partial<ProjectSession>;
  if (!Array.isArray(record.tabs)) return null;
  const tabs: string[] = [];
  const seen = new Set<string>();
  for (const item of record.tabs) {
    if (typeof item !== 'string' || !item.trim()) continue;
    const key = item.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    tabs.push(item);
    if (tabs.length >= SESSION_TAB_LIMIT) break;
  }
  return {
    tabs,
    activeTab: typeof record.activeTab === 'string' && record.activeTab.trim() ? record.activeTab : null,
    updatedAt: Number.isFinite(record.updatedAt) ? Number(record.updatedAt) : 0,
  };
}

/** 读全部会话 (按项目路径规范化后的键索引)。 */
export function loadSessions(): Record<string, ProjectSession> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const sessions: Record<string, ProjectSession> = {};
    for (const [key, value] of Object.entries(parsed)) {
      const session = normalizeSession(value);
      if (session) sessions[key] = session;
    }
    return sessions;
  } catch {
    return {};
  }
}

/** 读某个项目的会话; 没有记录时返回 null。 */
export function loadSession(projectPath: string): ProjectSession | null {
  return loadSessions()[bindingKey(projectPath)] ?? null;
}

/** 写入某个项目的会话, 顺带按更新时间淘汰过旧的记录。 */
export function saveSession(projectPath: string, session: ProjectSession): void {
  try {
    const sessions = loadSessions();
    sessions[bindingKey(projectPath)] = session;
    const entries = Object.entries(sessions).sort((a, b) => b[1].updatedAt - a[1].updatedAt);
    const kept = Object.fromEntries(entries.slice(0, SESSION_PROJECT_LIMIT));
    localStorage.setItem(STORAGE_KEY, JSON.stringify(kept));
  } catch {
    // 存储不可用时静默忽略: 恢复选项卡是锦上添花, 不该影响打开项目
  }
}

/** 删除某个项目的会话 (项目被移入回收站时用)。 */
export function removeSession(projectPath: string): void {
  try {
    const sessions = loadSessions();
    delete sessions[bindingKey(projectPath)];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(sessions));
  } catch {
    // 同上
  }
}
